def parse_up_interfaces(text: str) -> list[str]:
    lines = text.splitlines()
    result = []
    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        protocol = parts[-1]
        if len(parts) >= 3 and parts[-2] == "down" and parts[-3] == "administratively":
            status = "administratively down"
        else:
            status = parts[-2]
        if status == "up" and protocol == "up":
            result.append(parts[0])
    return result
